WITH history AS (SELECT DATE_TRUNC(`event_date`, DAY) AS period, EXTRACT(DAYOFWEEK FROM `event_date`) AS dow, COUNT(*) AS cnt FROM `fake_project.dataset.orders` WHERE `event_date` >= DATE('2026-05-01') - INTERVAL 28 DAY AND `event_date` < DATE('2026-05-01') GROUP BY period, dow) SELECT dow, APPROX_QUANTILES(cnt, 100)[OFFSET(5)] AS p_lo, APPROX_QUANTILES(cnt, 100)[OFFSET(95)] AS p_hi, COUNT(*) AS n FROM history GROUP BY dow